<script>
import { Form, Head, Link } from '@inertiajs/vue3';
import InputError from '@scaffold/components/InputError.vue';
import PrimaryButton from '@scaffold/components/PrimaryButton.vue';
import { login } from '@app/routes';
import { store } from '@app/routes/register';

export default {
    components: { Form, InertiaHead: Head, InputError, Link, PrimaryButton },
    props: {
        passwordRules: String,
    },
    data() {
        return {
            registrationForm: store.form(),
            loginUrl: login.url(),
        };
    },
};
</script>

<template>
    <div>
        <InertiaHead title="Reģistrēties" />

        <div class="row justify-content-center">
            <div class="lg:col-4 md:col-6 sm:col-8 ms-auto me-auto">
                <div class="card registration-card">
                    <div class="card-header card-header-primary text-center">
                        <h1 class="card-title h4">Reģistrēties</h1>
                    </div>

                    <Form
                        v-bind="registrationForm"
                        :reset-on-success="['password', 'password_confirmation']"
                        v-slot="{ errors, processing }"
                    >
                        <div class="card-body">
                            <div class="form-group">
                                <label for="name">Vārds</label>
                                <input id="name" name="name" type="text" class="form-control" autocomplete="name" required />
                                <InputError :message="errors.name" />
                            </div>

                            <div class="form-group">
                                <label for="email">E-pasta adrese</label>
                                <input id="email" name="email" type="email" class="form-control" autocomplete="email" required />
                                <InputError :message="errors.email" />
                            </div>

                            <div class="form-group">
                                <label for="password">Parole</label>
                                <input
                                    id="password"
                                    name="password"
                                    type="password"
                                    class="form-control"
                                    autocomplete="new-password"
                                    :passwordrules="passwordRules"
                                    required
                                />
                                <InputError :message="errors.password" />
                            </div>

                            <div class="form-group">
                                <label for="password_confirmation">Apstiprināt paroli</label>
                                <input
                                    id="password_confirmation"
                                    name="password_confirmation"
                                    type="password"
                                    class="form-control"
                                    autocomplete="new-password"
                                    :passwordrules="passwordRules"
                                    required
                                />
                                <InputError :message="errors.password_confirmation" />
                            </div>
                        </div>

                        <div class="card-footer justify-content-center">
                            <PrimaryButton
                                type="submit"
                                class="btn btn-primary"
                                :disabled="processing"
                                data-test="register-user-button"
                            >
                                Izveidot kontu
                            </PrimaryButton>
                        </div>
                    </Form>

                    <p class="text-center mb-3">
                        Jau ir konts? <Link :href="loginUrl">Pieteikties</Link>
                    </p>
                </div>
            </div>
        </div>
    </div>
</template>

<style scoped>
    .registration-card .form-control:focus {
        outline: 2px solid transparent;
    }

    @media (max-width: 991.98px) {
        .registration-card .form-control {
            font-size: 1rem;
        }
    }
</style>
